{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/post-split.json
    A post header with the author, the reading figures, the tags and the actions. Axes: layout (center: tags, figures and an author card with share and save over a wide cover; split: beside the cover; outline: facts and related reading beside the cover), mediaSide, author (line, card, bio), cover (wide, square), actions (pair, wide, icons), tone.
    Props (p): id, post, labels, extras, level, layout, mediaSide, author, cover, actions, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_post = ($p['post'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_extras = ($p['extras'] ?? null)}
{var $v_level = ($p['level'] ?? 1)}
{var $v_layout = ($p['layout'] ?? 'split')}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{var $v_author = ($p['author'] ?? 'line')}
{var $v_cover = ($p['cover'] ?? 'wide')}
{var $v_actions = ($p['actions'] ?? 'pair')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{if ui_t(ui_eq($v_layout, 'center'))}
  {capture $f_1}
    {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_post, ['title']), 'ratio' => (ui_t(ui_eq($v_layout, 'center')) ? '21/9' : (ui_t(ui_eq($v_cover, 'square')) ? '1/1' : '4/3'))]])|noescape}
  {/capture}
  {capture $c_2}
    {=ui_include('blocks/post-tags.latte', ['p' => ['tags' => ui_get($v_extras, ['tags']), 'align' => 'center']])|noescape}
    {=ui_include('blocks/post-stats.latte', ['p' => ['post' => $v_post, 'extras' => $v_extras, 'labels' => $v_labels, 'align' => 'center']])|noescape}
    {=ui_include('blocks/post-author.latte', ['p' => ['post' => $v_post, 'extras' => $v_extras, 'labels' => $v_labels, 'mode' => 'card', 'share' => true, 'className' => ui_cnv(['mx-auto w-full max-w-md'])]])|noescape}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => ui_get($v_post, ['title']), 'lead' => ui_get($v_post, ['excerpt']), 'heading' => ['badge' => ui_get($v_post, ['category']), 'level' => $v_level], 'tone' => $v_tone, 'media' => ['show' => true], 'align' => 'center', 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_1], 'children' => $c_2])|noescape}
{else}
  {capture $f_3}
    {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_post, ['title']), 'ratio' => (ui_t(ui_eq($v_layout, 'center')) ? '21/9' : (ui_t(ui_eq($v_cover, 'square')) ? '1/1' : '4/3'))]])|noescape}
  {/capture}
  {capture $c_4}
    {if ui_t(ui_eq($v_layout, 'outline'))}
      {=ui_include('blocks/post-outline.latte', ['p' => ['post' => $v_post, 'extras' => $v_extras, 'labels' => $v_labels]])|noescape}
    {else}
      {=ui_include('blocks/post-author.latte', ['p' => ['post' => $v_post, 'extras' => $v_extras, 'labels' => $v_labels, 'mode' => $v_author]])|noescape}
      {if ui_t(!(ui_eq($v_author, 'line')))}
        {=ui_include('blocks/post-stats.latte', ['p' => ['post' => $v_post, 'extras' => $v_extras, 'labels' => $v_labels]])|noescape}
      {/if}
      {=ui_include('blocks/post-tags.latte', ['p' => ['tags' => ui_get($v_extras, ['tags'])]])|noescape}
    {/if}
    {=ui_include('blocks/post-actions.latte', ['p' => ['labels' => $v_labels, 'mode' => $v_actions]])|noescape}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => ui_get($v_post, ['title']), 'lead' => ui_get($v_post, ['excerpt']), 'heading' => ['badge' => ui_get($v_post, ['category']), 'level' => $v_level], 'tone' => $v_tone, 'media' => ['show' => true, 'side' => $v_mediaSide], 'layout' => 'split', 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_3], 'children' => $c_4])|noescape}
{/if}
